	router.POST(options.BaseURL+"/dns/conf/apply", wrapper.ApplyDnsConf)
	router.GET(options.BaseURL+"/dns/settings", wrapper.GetDnsSettings)
	router.PUT(options.BaseURL+"/dns/settings", wrapper.UpdateDnsSettings)
	router.GET(options.BaseURL+"/dns/settings/ttl-overrides", wrapper.ListTtlOverrides)
	router.PUT(options.BaseURL+"/dns/settings/ttl-overrides", wrapper.UpsertTtlOverride)
	router.POST(options.BaseURL+"/dns/cache/flush", wrapper.FlushCache)
	router.POST(options.BaseURL+"/dns/diagnose", wrapper.DiagnoseDns)
	router.GET(options.BaseURL+"/dns/blocklists", wrapper.ListBlocklists)
	router.POST(options.BaseURL+"/dns/blocklists", wrapper.CreateBlocklist)
	router.POST(options.BaseURL+"/dns/blocklists/:listId", wrapper.SyncBlocklist)
	router.GET(options.BaseURL+"/dns/blocklists/:listId/entries", wrapper.ListBlocklistEntries)
	router.POST(options.BaseURL+"/dns/blocklists/:listId/entries", wrapper.AddBlocklistEntry)
	router.GET(options.BaseURL+"/dns/policy-groups", wrapper.ListPolicyGroups)
	router.POST(options.BaseURL+"/dns/policy-groups", wrapper.CreatePolicyGroup)
	router.POST(options.BaseURL+"/dns/policy-groups/:groupId/compile", wrapper.CompilePolicyGroup)
	router.GET(options.BaseURL+"/dns/zones", wrapper.ListDnsZones)
	router.POST(options.BaseURL+"/dns/zones", wrapper.CreateDnsZone)
	router.GET(options.BaseURL+"/dns/zones/:zoneId/records", wrapper.ListDnsRecords)
	router.POST(options.BaseURL+"/dns/zones/:zoneId/records", wrapper.CreateDnsRecord)
	router.GET(options.BaseURL+"/dns/zones/:zoneId/linked", wrapper.ListLinkedRecords)
	router.DELETE(options.BaseURL+"/dns/zones/:zoneId", wrapper.DeleteDnsZone)
	router.GET(options.BaseURL+"/dns/zones/:zoneId", wrapper.ExportDnsZone)
	router.GET(options.BaseURL+"/forward-rules", wrapper.ListForwardRules)
	router.POST(options.BaseURL+"/forward-rules", wrapper.CreateForwardRule)
	router.DELETE(options.BaseURL+"/forward-rules/:ruleId", wrapper.DeleteForwardRule)
	router.PATCH(options.BaseURL+"/forward-rules/:ruleId", wrapper.UpdateForwardRule)
	router.GET(options.BaseURL+"/upstreams", wrapper.ListUpstreams)
	router.POST(options.BaseURL+"/upstreams", wrapper.CreateUpstream)
